olygon(0 0,100% 0,100% 100%,0 100%);text-align:center;transform:rotate(calc(-1 * var(--tilt,0deg)));transition:transform .75s cubic-bezier(.2,.9,.15,1.35)}.pan.left{left:0;translate:-50% 0}.pan.right{right:0;translate:50% 0}.pan:after{content:"";position:absolute;bottom:4px;left:-12px;width:115px;height:14px;background:linear-gradient(#ddb876,#926c40);border-radius:50%}.pan .pile{position:absolute;bottom:25px;left:0;width:100%;font:28px/1 Fraunces;color:var(--rust);text-shadow:2px 2px 0 #f1d3a4;white-space:nowrap}.pan.right .pile{color:var(--teal)}.balance-status{text-align:center;min-height:44px;font-family:Fraunces;font-size:1.22rem}.balance-status small{display:block;font:11px 'DM Mono',monospace;color:var(--muted)}.sides{display:grid;grid-template-columns:1fr 1fr;gap:17px;margin-top:21px}.side{border-top:3px solid var(--rust);padding-top:13px}.side:nth-child(2){border-color:var(--teal)}.side-title{font:500 11px 'DM Mono',monospace;text-transform:uppercase;letter-spacing:.17em;display:flex;justify-content:space-between;gap:5px;margin-bottom:13px}.side-title b{color:var(--muted);font-weight:400;white-space:nowrap}.row{display:grid;grid-template-columns:minmax(85px,1fr) 34px 22px 34px;gap:4px;align-items:center;margin:6px 0;font-size:13px}.row .name{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.row button{height:32px;border:1px solid #bcad95;background:#f8f0df;color:var(--ink);font:21px/1 Georgia}.row button:hover{background:var(--brass)}.row output{text-align:center;font:13px 'DM Mono',monospace}.guide{background:#e9decb;border:1px solid #d2c2a9;padding:25px;align-self:start}.guide h3{font:500 1.8rem Fraunces;margin:6px 0 15px}.guide p{font-size:13px;color:#554f4b}.guide .fact{border-top:1px solid #c5b69e;padding:11px 0 8px;display:flex;justify-content:space-between;gap:7px;font:12px 'DM Mono',monospace}.guide .fact strong{white-space:nowrap}.guide .note{margin:15px 0 0;font:11px/1.55 'DM Mono',monospace;color:#746a62}.reset{border:1px solid #786551;background:none;color:#4a4036;font:11px 'DM Mono',monospace;padding:8px 11px;margin-top:20px}.reset:hover{background:#e2d1b5}.challenge{padding:72px 0;background:#2a2832;color:#f8eede;position:relative;overflow:hidden}.challenge:before{content:"";position:absolute;right:-130px;top:-100px;width:360px;height:360px;border:1px solid #8e754d;border-radius:50%;box-shadow:0 0 0 35px #ffffff08,0 0 0 70px #ffffff05}.challenge .wrap{position:relative}.challenge-grid{display:grid;grid-template-columns:1fr 1fr;gap:75px;align-items:center}.challenge h2{margin:.3em 0}.challenge p{max-width:470px;color:#d4c8bd}.dial{background:#f4e9d6;color:var(--ink);padding:32px;box-shadow:12px 12px 0 #11101655}.dial label{display:block;font:500 11px 'DM Mono',monospace;letter-spacing:.11em;text-transform:uppercase}.dial .number{font:500 clamp(3.5rem,8vw,6rem)/1 Fraunces;color:var(--rust);margin:16px 0 8px}.dial .number span{font:18px 'DM Mono',monospace;color:var(--muted)}input[type=range]{width:100%;accent-color:var(--rust);height:35px;margin:12px 0;cursor:pointer}.dial-result{border-top:1px solid #cbb9a1;padding-top:17px;font-size:14px;min-height:94px}.dial-result strong{font-family:Fraunces;font-size:1.45rem}.source{padding:43px 0 60px}.source a{color:#80533a;text-underline-offset:3px}.source p{max-width:750px;font-size:14px}.footnote{font:11px/1.7 'DM Mono',monospace;color:#71665c}@media(max-width:800px){.hero{grid-template-columns:1fr;min-height:0;gap:35px;padding-top:45px}.hero img{max-height:360px}.workshop,.challenge-grid{grid-template-columns:1fr;gap:23px}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.guide h3,.guide>p,.guide .note,.reset{grid-column:1/-1}.guide .fact{display:block}.guide .fact strong{display:block}}@media(max-width:540px){.wrap{padding-left:16px;padding-right:16px}.hero{padding-bottom:63px}.mast{align-items:start}.mast a{max-width:90px;text-align:right}.section{padding-top:54px;padding-bottom:62px}.heading{display:block}.heading p{margin-top:14px}.bench{padding:16px 13px 22px;box-shadow:4px 4px 0 #ded1bd}.sides{gap:9px}.row{grid-template-columns:minmax(0,1fr) 29px 16px 29px;font-size:11px;gap:2px}.row button{height:32px}.side-title{display:block;font-size:10px}.side-title b{display:block}.scale{height:168px}.scale .post{height:83px}.beam{top:45px}.pan{width:65px;height:78px}.pan:after{width:82px;left:-8px}.pan .pile{font-size:21px}.guide{grid-template-columns:1fr 1fr}.guide .fact:last-of-type{grid-column:1/-1}.challenge{padding:55px 0}.dial{padding:24px}}
